// ── Choisir cohorte v2 ──────────────────────────────────────────────
// pipeline EN ROUTE = pipeline_id 2
// stage "Anciennes cohortes" = id 20
const PIPELINE_ID = 2;
const ARCHIVED_STAGE_ID = 20;

const norm = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const MONTHS = ['jan','fev','mar','avr','mai','juin','juil','aou','sep','oct','nov','dec'];
const monthIdx = tok => MONTHS.findIndex(m => norm(tok).startsWith(m));
const pad = n => String(n).padStart(2,'0');
const toISO = (y,m,d) => `${y}-${pad(m+1)}-${pad(d)}`;

const today = new Date().toLocaleDateString('en-CA',{timeZone:'America/Toronto'});
const [ty,tm,td] = today.split('-').map(Number);
const todayMs = Date.UTC(ty,tm-1,td);
const resolveYear = (m,d) => {
  let best=null;
  for(const y of [ty-1,ty,ty+1]){
    const diff=Math.abs(Date.UTC(y,m,d)-todayMs);
    if(!best||diff<best.diff) best={y,diff};
  }
  return best.y;
};

// 1. Stages du pipeline EN ROUTE uniquement
const raw = $input.first().json.data || [];
const stages = raw
  .filter(s => s.pipeline_id === PIPELINE_ID)
  .map(s => {
    const mm = String(s.name).match(/^\s*cohorte\s+(\d+)\s*\(\s*(\d{1,2})\s+([^)\s]+)\s*\)/i);
    if(!mm) return null;
    const m = monthIdx(mm[3]);
    if(m<0) return null;
    const d = +mm[2];
    return { stageId:s.id, stageName:s.name, number:+mm[1], date:toISO(resolveYear(m,d),m,d) };
  }).filter(Boolean);

// 2. Lire la commande Telegram
const inp = $('Entrée').first().json;
const text = String(inp.text||inp.message?.text||'').trim();
const arg = text.replace(/^\/facture(@\w+)?/i,'').trim();

let chosen;
if(/^\d{1,3}$/.test(arg)){
  const num = +arg;
  chosen = stages.find(s => s.number===num);
  if(!chosen){
    // Cohorte non trouvée dans les stages actifs → vérifier si archivée
    return [{json:{
      stageId: ARCHIVED_STAGE_ID,
      stageName: `Cohorte ${num} (archivée)`,
      number: num,
      date: null,
      today,
      archived: true,
      cohortNumber: num
    }}];
  }
} else if(arg){
  const dm = arg.match(/^(\d{1,2})\s+(\S+)$/);
  const m = dm ? monthIdx(dm[2]) : -1;
  if(m<0) throw new Error(`Argument non reconnu : "${arg}" — utilisez un numéro (ex. 72) ou une date (ex. 21 oct)`);
  const iso = toISO(resolveYear(m,+dm[1]),m,+dm[1]);
  chosen = stages.find(s => s.date===iso);
  if(!chosen) throw new Error(`Aucun stage actif pour la date ${iso} — si archivée, utilisez /facture <numéro>`);
} else {
  chosen = stages.filter(s=>s.date<=today).sort((a,b)=>b.date.localeCompare(a.date))[0];
  if(!chosen) throw new Error('Aucune cohorte démarrée à ce jour dans le pipeline EN ROUTE');
}

return [{json:{...chosen, today, archived:false, cohortNumber:chosen.number}}];

// ── Filtrer Djamel v3 — pagination manuelle (2 pages max pour Anciennes cohortes) ──
const norm = s => String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const c = $('Choisir cohorte').first().json;

// Récupérer tous les items de l'input (page 1 + page 2 si dispo)
const allItems = $input.all();
const deals = allItems.flatMap(item => item.json.data || []);

if(deals.length === 0){
  throw new Error(`Aucun deal retourné pour le stage "${c.stageName}"`);
}

const mine = deals.filter(d => {
  const owner = d.owner_name || d.user_id?.name || '';
  const isWon = d.status === 'won';
  const isDjamel = norm(owner).startsWith('djamel');
  if(!isWon || !isDjamel) return false;
  if(c.archived){
    // Chercher dans les notes du deal (chargées séparément via _notes ou notes_count)
    // Pour l'instant on filtre sur title contenant le numéro — sera remplacé par notes en étape B
    return true; // on garde tous les Won Djamel, le filtrage par note se fera après
  }
  return true;
});

const names = [...new Set(
  mine.map(d => String(d.title||d.person_name||'').trim()).filter(Boolean)
)];

if(names.length === 0){
  throw new Error(`Aucun deal Won de Djamel dans "${c.stageName}"`);
}
if(names.length > 20){
  throw new Error(`${names.length} prospects dépasse la limite de 20 du gabarit`);
}

return [{json:{
  cohortNumber: c.cohortNumber,
  stageName: c.stageName,
  cohortDate: c.date || c.today,
  today: c.today,
  archived: c.archived,
  count: names.length,
  names,
  amount: names.length * 150,
  totalDeals: deals.length,
  ignored: deals.length - mine.length
}}];
